<script setup>
import { ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MEmptyState from '../../../components/mds/MEmptyState.vue'; import MInput from '../../../components/mds/MInput.vue'; import MTag from '../../../components/mds/MTag.vue';
const props = defineProps({ rows: { type: Array, default: () => [] }, total: Number, page: Number, pageSize: Number, search: String, loading: Boolean }); const emit = defineEmits(['search', 'page', 'open']); const query = ref(props.search || ''); watch(() => props.search, (value) => { query.value = value || ''; });
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><div class="mx-auto max-w-[1200px] space-y-4"><header class="rounded-lg bg-[var(--mds-bg)] px-5 py-4 shadow-[var(--mds-shadow-card)]"><h1 class="text-[20px] font-semibold">Giải thưởng</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Danh sách giải thưởng từ projection R062.</p><form class="mt-4 flex max-w-[560px] gap-2" @submit.prevent="emit('search', query.trim())"><MInput v-model="query" placeholder="Tìm giải thưởng hoặc đơn vị tổ chức…" /><MButton variant="primary" :loading="loading" @click="emit('search', query.trim())">Tìm</MButton></form></header><section class="overflow-hidden rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]"><div class="border-b border-[var(--mds-border-light)] px-5 py-3 text-[13px] text-[var(--mds-text-secondary)]">{{ total || 0 }} giải thưởng</div><div v-if="rows.length" class="overflow-x-auto"><table class="w-full min-w-[700px] text-left"><thead class="bg-[var(--mds-bg-page)] text-[12px] text-[var(--mds-text-secondary)]"><tr><th class="px-5 py-3">Giải thưởng</th><th class="px-3 py-3">Hạn nộp</th><th class="px-3 py-3">Đơn vị tổ chức</th><th class="px-5 py-3">Trạng thái</th></tr></thead><tbody class="divide-y divide-[var(--mds-border-light)]"><tr v-for="row in rows" :key="row.id" tabindex="0" class="cursor-pointer hover:bg-[var(--mds-bg-page)] focus-within:bg-[var(--mds-bg-page)]" @click="emit('open', row.id)" @keydown.enter="emit('open', row.id)" @keydown.space.prevent="emit('open', row.id)"><td class="px-5 py-3"><strong class="block text-[13px]">{{ row.name }}</strong><span class="text-[12px] text-[var(--mds-text-secondary)]">{{ row.scope }}</span></td><td class="px-3 py-3 text-[13px]">{{ row.deadline }}</td><td class="px-3 py-3 text-[13px]">{{ row.organizer }}</td><td class="px-5 py-3"><MTag color="neutral">{{ row.status }}</MTag></td></tr></tbody></table></div><MEmptyState v-else-if="!loading" title="Chưa có giải thưởng" description="Giải thưởng được phép xem sẽ xuất hiện tại đây." /><div v-else class="p-8 text-center text-[13px] text-[var(--mds-text-secondary)]">Đang tải giải thưởng…</div></section><footer class="flex justify-end gap-2"><MButton variant="neutral" :disabled="loading || page <= 1" @click="emit('page', page - 1)">Trang trước</MButton><MButton variant="neutral" :disabled="loading || page * pageSize >= total" @click="emit('page', page + 1)">Trang sau</MButton></footer></div></section></template>
